SELECT id, budget, ROW_NUMBER() OVER (ORDER BY budget DESC, id) AS seq_no, AVG(budget) OVER (ORDER BY budget, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS budget_avg_3_prior, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget, id) AS row_seq, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_budget, CUME_DIST() OVER w_grp AS budget_cume_dist FROM departments WINDOW w_grp AS (PARTITION BY location ORDER BY budget DESC NULLS FIRST)
